(function(){'use strict';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),norm=v=>String(v||'').toLowerCase(),P=window.DegreeProgramOpportunities;
let catalog,data,rows=[],limit=30,preset='all',restoreFocus=null,splits=new Map(),index={plans:{},subjects:{}};
const levels={associate:'Associate',bachelor:'Bachelor’s',master:'Master’s',doctorate:'Doctoral',specialist:'Specialist'};
const mark=school=>({'Western Governors University':'WGU','Liberty University':'LU','Thomas Edison State University':'TESU','Grand Canyon University':'GCU','Southern New Hampshire University':'SNHU'})[school]||String(school||'').split(/\s+/).filter(w=>/^[A-Z]/.test(w)).map(w=>w[0]).join('').slice(0,4);
// The reviewed starting-route mix, when a saved research baseline exists. Text beside the bar carries the numbers.
function split(p){const s=splits.get(p.id);if(!s)return '';const short=({'Western Governors University':'WGU','Liberty University':'Liberty'})[p.school]||'the university',unit=p.school==='Western Governors University'?'competency units':'credits',share=Math.round(s.outside/s.total*100);return '<div class="pf-split"><div class="pf-split-track" aria-hidden="true"><span class="pf-split-outside" style="flex-grow:'+s.outside+'"></span><span class="pf-split-school" style="flex-grow:'+s.university+'"></span></div><p class="pf-split-text"><span class="pf-split-label">Starting route</span> <strong>'+s.outside+'</strong> outside + <strong>'+s.university+'</strong> at '+esc(short)+' = '+s.total+' '+unit+' <span>· '+share+'% proposed outside</span></p></div>';}
const schoolFor=p=>P.schoolFor(data,p),price=p=>P.priceText(p,schoolFor(p)),pace=p=>P.paceText(p),isSelf=p=>['competency-subscription','self-paced'].includes(p.paceModel);
// Review tier, browsing subjects and open questions come from data/plan-library-index.json.
const info=p=>index.plans[p.id]||{tier:'reviewed',subjects:[],questions:[]},needsConfirmation=p=>info(p).tier==='confirmation',shareOf=p=>{const s=splits.get(p.id);return s?Math.round(s.outside/s.total*100):null;};
const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v);
const confirmBadge='<span class="pf-badge pf-badge-confirm">Needs school confirmation</span>';
function matches(p){const subject=$('program-subject').value,minShare=Number($('program-share').value)||0;if(subject&&!info(p).subjects.includes(subject))return false;if(minShare&&!((shareOf(p)??-1)>=minShare))return false;if(!$('program-confirm').checked&&needsConfirmation(p))return false;
const q=norm($('program-search').value).trim(),policy=p.effectiveTransferPolicy||schoolFor(p)?.transferPolicy||{},credit=$('program-credit').value;return(!$('program-school').value||p.school===$('program-school').value)&&(!$('program-level').value||p.level===$('program-level').value)&&(!q||norm([p.school,p.title,p.id,pace(p)].join(' ')).includes(q))&&(preset==='all'||preset==='self-paced'&&isSelf(p)||['online','campus'].includes(preset)&&p.modalities?.includes(preset))&&(!credit||['accepted','case-by-case'].includes(policy[credit]?.status));}
function render(){
 $('program-college-tip').hidden=$('program-credit').value!=='institutional'||['master','doctorate','specialist'].includes($('program-level').value);
 const sortKey=$('program-sort').value,filtered=rows.filter(matches).sort(sortKey==='outside'?(a,b)=>(shareOf(b)??-1)-(shareOf(a)??-1)||Number(needsConfirmation(a))-Number(needsConfirmation(b))||a.title.localeCompare(b.title):sortKey==='az'?(a,b)=>a.title.localeCompare(b.title)||a.school.localeCompare(b.school):sortKey==='school'?(a,b)=>a.school.localeCompare(b.school)||a.title.localeCompare(b.title):(a,b)=>Number(needsConfirmation(a))-Number(needsConfirmation(b))||Number(isSelf(b))-Number(isSelf(a))||a.school.localeCompare(b.school)||a.title.localeCompare(b.title));
 const pending=filtered.filter(needsConfirmation).length;$('program-legend').hidden=!pending;$('program-count').textContent=!filtered.length?'No course plans match these filters':filtered.length+' course plan'+(filtered.length===1?'':'s')+' · '+new Set(filtered.map(p=>p.school)).size+' school'+(new Set(filtered.map(p=>p.school)).size===1?'':'s')+(pending?' · '+pending+' need school confirmation':'');
 document.querySelectorAll('[data-preset]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.preset===preset)));
 $('program-results').innerHTML=filtered.slice(0,limit).map(p=>{
  const choiceCount=DegreeProgramCatalog.planChoiceCount(p,catalog),formats=p.modalities.map(m=>m==='campus'?'On campus':'Online').join(' · ');
  const href=splits.has(p.id)?'portal.html?usePlan='+encodeURIComponent(p.id):'portal.html?school='+encodeURIComponent(p.school)+'&program='+encodeURIComponent(p.id)+'&level='+encodeURIComponent(p.level);
  return '<article class="pf-program" data-program="'+esc(p.id)+'"><div class="pf-main-col"><div class="pf-school-row"><span class="pf-mark" aria-hidden="true">'+esc(mark(p.school))+'</span><span class="pf-school">'+esc(p.school)+'</span></div><h2>'+esc(p.title)+'</h2><p class="pf-meta">'+esc(levels[p.level]||p.level)+' · '+esc(formats)+'</p><div class="pf-badges"><span class="pf-badge">'+esc(pace(p))+'</span>'+(needsConfirmation(p)?confirmBadge:'<span class="pf-badge pf-badge-ready">Reviewed plan</span>')+'<span class="pf-badge">Full requirement plan</span>'+(choiceCount>0?'<span class="pf-badge">'+choiceCount+' course choice'+(choiceCount===1?'':'s')+' to make</span>':'')+'</div>'+split(p)+(needsConfirmation(p)?'<p class="pf-confirm-note"><strong>Open question:</strong> '+esc(info(p).questions[0]||'Some details still need confirmation with the school.')+(info(p).questions.length>1?' <span>+'+(info(p).questions.length-1)+' more in details</span>':'')+'</p>':'')+'</div><div class="pf-side"><div class="pf-price">'+(info(p).estimate?'Planning estimate '+money(info(p).estimate.min)+'–'+money(info(p).estimate.max)+'<small>Before aid · tuition, fees and outside courses</small>':esc(price(p))+'<small>Tuition and course details in the plan</small>')+'</div><a class="pf-button pf-button-primary pf-open-plan" href="'+esc(href)+'">See courses</a><button type="button" data-program-details="'+esc(p.id)+'">College &amp; transfer details</button></div></article>';
 }).join('')||'<div class="pf-empty"><h2>No course plan matches these filters.</h2><p>Try different choices, or create a plan for your exact degree.</p><button type="button" id="program-reset">Clear filters</button><a class="pf-plan-link" href="request-plan.html">Build from a degree link</a></div>';
 $('program-more').hidden=filtered.length<=limit;
}
function details(id){
 const p=rows.find(p=>p.id===id);if(!p)return;
 restoreFocus=document.activeElement;const choices=DegreeProgramCatalog.planChoiceCount(p,catalog),school=schoolFor(p),href=splits.has(p.id)?'portal.html?usePlan='+encodeURIComponent(p.id):'portal.html?school='+encodeURIComponent(p.school)+'&program='+encodeURIComponent(p.id)+'&level='+encodeURIComponent(p.level);
 $('program-dialog-content').innerHTML='<div class="pf-dialog-heading"><span class="pf-school">'+esc(p.school)+'</span><h2>'+esc(p.title)+'</h2><p>'+esc(levels[p.level]||p.level)+' · '+esc(pace(p))+'</p></div>'+(needsConfirmation(p)?'<section class="pf-confirm-detail"><h3>What still needs school confirmation</h3><ul>'+info(p).questions.map(q=>'<li>'+esc(q)+'</li>').join('')+'</ul><p>The course plan is complete, but these points are not yet confirmed in the school’s published rules. Ask the school about them before paying for outside courses.</p></section>':'')+P.detailsHTML(p,school)+'<p class="pf-map-note">Includes the full degree requirements. '+(choices>0?choices+' course choice'+(choices===1?'':'s')+' to make. ':'')+'Each course shows its degree placement and any specific conditions. Your college records the final credit award.</p><div class="pf-dialog-actions"><a class="pf-button pf-button-primary" data-choose-program href="'+esc(href)+'">Build this degree plan</a><a href="school.html?school='+encodeURIComponent(p.school)+'">Read about this school</a><a href="'+esc(p.url||school?.url)+'" target="_blank" rel="noopener">Official program source</a></div>';
 $('program-dialog').showModal();
}
function reset(){for(const id of['program-search','program-school','program-level','program-credit','program-subject','program-share','program-sort'])$(id).value='';$('program-confirm').checked=true;preset='all';limit=30;render();}
$('program-filters').addEventListener('submit',e=>{e.preventDefault();limit=30;render();});
for(const type of ['input','change'])$('program-filters').addEventListener(type,()=>{limit=30;render();});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.preset){preset=b.dataset.preset;limit=30;render();}else if(b.dataset.programDetails)details(b.dataset.programDetails);else if(b.id==='program-more'){limit+=30;render();}else if(b.id==='program-reset')reset();else if(b.id==='program-dialog-close')$('program-dialog').close();});
$('program-sort').addEventListener('change',()=>{limit=30;render();});
$('program-dialog').addEventListener('close',()=>restoreFocus?.isConnected&&restoreFocus.focus({preventScroll:true}));
(async()=>{try{
 const loaded=await Promise.all(['data/pathways.json','data/program-catalog.json','data/opportunity-catalog.json','data/credit-sources.json'].map(async url=>{const r=await fetch(url);if(!r.ok)throw Error('The degree plans could not load. Please reload.');return r.json();}));
 data=loaded[2];const sources=loaded[3];
 // The finder index is an enhancement: without it, only reviewed (published) plans are listed.
 try{const r=await fetch('data/plan-library-index.json');const value=r.ok?await r.json():null;index={plans:value?.plans&&typeof value.plans==='object'?value.plans:{},subjects:value?.subjects&&typeof value.subjects==='object'?value.subjects:{}};}catch{index={plans:{},subjects:{}};}
 $('program-college-tip').querySelector('div').innerHTML=sources.sources.filter(source=>['asu-ulc','tel','cpa-credits','outlier'].includes(source.id)).map(source=>'<p><a href="credit-sources/'+encodeURIComponent(source.id)+'/">'+esc(source.name)+'</a><small>'+esc(source.creditBasis)+'</small></p>').join('');
 catalog=await DegreeProgramCatalog.loadIndex(DegreeProgramCatalog.merge(loaded[0],loaded[1]));
 if(typeof DegreeProgramCatalog.publishedPlans!=='function'||catalog.publicationIndex?.available===false)throw Error('We couldn’t load the reviewed degree plans. Reload to try again. Your saved plan is safe.');
 // Reviewed plans plus complete plans that still need school confirmation (labelled); both open in the planner.
 const published=DegreeProgramCatalog.publishedPlans(catalog).filter(p=>P.availability(p).canChoose),publishedIds=new Set(published.map(p=>p.id));
 rows=[...published,...(typeof DegreeProgramCatalog.isPlanAvailable==='function'?(catalog.pathways||[]).filter(p=>!publishedIds.has(p.id)&&p.modelId&&index.plans[p.id]?.tier==='confirmation'&&DegreeProgramCatalog.isPlanAvailable(p,catalog)&&P.availability(p).canChoose):[])];
 try{const r=await fetch('data/baseline-index.json');const baselineIndex=r.ok?await r.json():null;for(const b of Object.values(baselineIndex?.baselines||{})){const t=b.summary||{};if(!Number.isFinite(t.transferCredits)||!Number.isFinite(t.universityCredits))continue;splits.set(b.pathwayId,{outside:t.transferCredits,university:t.universityCredits,total:Number.isFinite(t.totalCredits)?t.totalCredits:t.transferCredits+t.universityCredits});}}catch{}
 const subjectIds=[...new Set(rows.flatMap(p=>info(p).subjects))];$('program-subject').innerHTML='<option value="">All subjects</option>'+Object.entries(index.subjects).filter(([id])=>subjectIds.includes(id)).map(([id,label])=>'<option value="'+esc(id)+'">'+esc(label)+'</option>').join('');
 const schools=[...new Set(rows.map(p=>p.school))].sort();
 $('program-school').innerHTML='<option value="">All schools</option>'+schools.map(s=>'<option value="'+esc(s)+'">'+esc(s)+'</option>').join('');
 const params=new URLSearchParams(location.search);if(schools.includes(params.get('school')))$('program-school').value=params.get('school');if(params.has('q'))$('program-search').value=params.get('q');if(['self-paced','campus','online'].includes(params.get('type')))preset=params.get('type');if(index.subjects[params.get('subject')])$('program-subject').value=params.get('subject');if(['outside','az','school'].includes(params.get('sort')))$('program-sort').value=params.get('sort');
 $('program-coverage').querySelector('div').innerHTML='<p>'+rows.length+' course plans from '+schools.length+' schools. Each includes every degree requirement, researched outside-course matches and required university coursework.</p><p><strong>Reviewed plans</strong> passed every DegreeSteps publication check. <strong>Plans that need school confirmation</strong> are complete, but at least one school rule or course match is not yet confirmed in the school’s published sources; each card names the open question. Your school makes the final decision on transfer credit.</p><p>Need a different degree? <a href="request-plan.html">Build a plan from its degree link</a>.</p>';
 render();
 
}catch(e){$('program-count').textContent='';$('program-error').hidden=false;$('program-error').textContent=e.message;}})();
}());
